import sympy as sp

# Top-level setup for potential witness expressions
I2 = sp.eye(2)
I3 = sp.eye(3)
O2 = sp.zeros(2, 2)
O3 = sp.zeros(3, 3)

CONDITION_LABELS = [
    "H_1: T is a linear operator",
    "H_2: v is a vector in V",
    "H_3: W is the T-cyclic subspace generated by v",
    "¬Q: W is not T-invariant, or there exists a T-invariant subspace U containing v such that W is not a subset of U"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness):
    try:
        if isinstance(witness, dict):
            T = witness.get('T')
            v = witness.get('v')
            W = witness.get('W')
            U = witness.get('U')
        elif isinstance(witness, (list, tuple)):
            if len(witness) == 3:
                T, v, W = witness
                U = None
            elif len(witness) == 4:
                T, v, W, U = witness
            else:
                return [False, False, False, False]
        else:
            return [False, False, False, False]
    except Exception:
        return [False, False, False, False]

    def to_matrix(obj, dim):
        if isinstance(obj, sp.MatrixBase):
            return obj
        if isinstance(obj, (list, tuple)):
            if len(obj) == 0:
                return sp.zeros(dim, 1)
            if all(isinstance(x, sp.MatrixBase) for x in obj):
                if all(x.shape == (dim, 1) for x in obj):
                    return sp.Matrix.hstack(*obj)
        return None

    # H1: T is a linear operator
    try:
        h1 = isinstance(T, sp.MatrixBase) and T.is_square
    except Exception:
        h1 = False

    if not h1:
        return [False, False, False, False]

    dim = T.shape[0]

    # H2: v is a vector in V
    try:
        h2 = isinstance(v, sp.MatrixBase) and v.shape == (dim, 1)
    except Exception:
        h2 = False

    # H3: W = span{v, T(v), T^2(v), ...}
    try:
        W_mat = to_matrix(W, dim)
        if W_mat is None:
            h3 = False
        else:
            # Compute the Krylov subspace span{v, T(v), ..., T^{dim-1}(v)}
            vecs = [v]
            curr = v
            for _ in range(dim - 1):
                curr = T * curr
                vecs.append(curr)
            S = sp.Matrix.hstack(*vecs)
            
            rank_S = S.rank()
            rank_W = W_mat.rank()
            rank_WS = sp.Matrix.hstack(W_mat, S).rank()
            h3 = (rank_W == rank_S) and (rank_WS == rank_S)
    except Exception:
        h3 = False

    # ¬Q: W is not T-invariant OR (U is a T-invariant subspace containing v AND W is not a subset of U)
    try:
        if W_mat is None:
            neg_q = False
        else:
            # Check if W is T-invariant
            TW = T * W_mat
            rank_W = W_mat.rank()
            rank_WTW = sp.Matrix.hstack(W_mat, TW).rank()
            W_is_invariant = (rank_WTW == rank_W)

            if not W_is_invariant:
                neg_q = True
            else:
                U_mat = to_matrix(U, dim) if U is not None else None
                if U_mat is not None:
                    # Check if U is T-invariant
                    TU = T * U_mat
                    rank_U = U_mat.rank()
                    rank_UTU = sp.Matrix.hstack(U_mat, TU).rank()
                    U_is_invariant = (rank_UTU == rank_U)

                    # Check if v is in U
                    rank_Uv = sp.Matrix.hstack(U_mat, v).rank()
                    v_in_U = (rank_Uv == rank_U)

                    # Check if W is a subset of U
                    rank_UW = sp.Matrix.hstack(U_mat, W_mat).rank()
                    W_in_U = (rank_UW == rank_U)

                    neg_q = U_is_invariant and v_in_U and not W_in_U
                else:
                    neg_q = False
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]